interface UIFactory {
    fun button(label: String): Button
    fun slider(min: Int, max: Int): Slider
    companion object {
        fun forPlatform(p: String): UIFactory = when (p) {
            "ios" -> Cupertino
            "android" -> Material
            else -> error("unknown platform: $p")
        }
    }
}

object Material : UIFactory {
    override fun button(label: String) = Button(label, style = "elevated")
    override fun slider(min: Int, max: Int) = Slider(min, max, track = "material")
}
